<?php
/** Tabler card/chat style comments; moderation and Yii2 CSRF remain unchanged. */
$user=Yii::$app->user->identity;
?>
<section class="section community-comments community-scope"><div class="comments-heading"><h2>球迷留言</h2><span><?= count($items) ?> 条留言</span></div><div class="card comment-card"><div class="card-body"><div class="comment-compose"><span class="avatar comment-avatar" aria-hidden="true"><?= e(mb_substr($user?->displayName??'球迷',0,1)) ?></span><div class="comment-compose-main"><?php if(!$user): ?><div class="comment-guest"><p>你怎么看？</p><a class="button" href="/login">登录后留言 ↗</a></div><?php else: ?><form method="post" action="/comments"><?= csrf_field() ?><input type="hidden" name="entity_type" value="<?= e($type) ?>"><input type="hidden" name="entity_id" value="<?= (int)$id ?>"><label class="visually-hidden" for="comment-body-<?= (int)$id ?>">留言内容</label><textarea id="comment-body-<?= (int)$id ?>" name="body" placeholder="聊聊这场比赛，或说说你支持的球队……" required minlength="2" maxlength="1000" rows="3"></textarea><div class="comment-compose-footer"><span>审核后公开</span><button class="button" type="submit">提交留言 ↗</button></div></form><?php endif ?></div></div></div><?php if($items): ?><div class="card-footer comment-stream"><?php foreach($items as $c): ?><article class="chat-item"><span class="avatar" aria-hidden="true"><?= e(mb_substr($c->user?->displayName??'球迷',0,1)) ?></span><div class="chat-bubble"><div class="chat-bubble-title"><b><?= e($c->user?->displayName??'球迷') ?></b><time><?= e(date('m月d日 H:i',strtotime($c->created_at))) ?></time></div><p><?= nl2br(e($c->body)) ?></p></div></article><?php endforeach ?></div><?php else: ?><div class="comment-first"><span aria-hidden="true">○</span> 暂无留言，来聊聊你的看法。</div><?php endif ?></div></section>
